SELECT COUNT(*)
FROM kb_insurance_recommendation_tbl
WHERE spending_analysis_id = #{spendingAnalysisId}

SELECT insurance_product_id AS insuranceProductId, insurance_name AS insuranceName, insurance_category AS insuranceCategory, insurance_description AS insuranceDescription, monthly_premium AS monthlyPremium, insurance_image AS insuranceImage, application_url AS applicationUrl FROM kb_insurance_product_tbl
insurance_category = #{category}
ORDER BY insurance_category ASC, insurance_product_id ASC
